#include <stdbool.h>
#include <stdint.h>
/* Preserve source-PTS second anchors, but rate-limit on actual elapsed time.
 * Slow decode must not be downsampled again according to compressed PTS gaps.
 * No timers wait for a boundary and no missed wall-time slots are replayed. */
struct bili_live_pacer {
  bool valid;
  uint32_t anchor_pts,last_pts;
  uint64_t last_present_us;
};
enum bili_live_present {BILI_LIVE_SKIP_SLOT,BILI_LIVE_PRESENT,BILI_LIVE_ANCHOR};
static inline enum bili_live_present bili_live_present(
    struct bili_live_pacer *p,uint32_t pts,uint64_t now_us,unsigned period_us)
{
  if(p->valid&&(int32_t)(pts-p->last_pts)<=0)return BILI_LIVE_SKIP_SLOT;
  if(!p->valid||pts/1000!=p->anchor_pts/1000){
    p->valid=true;p->anchor_pts=p->last_pts=pts;p->last_present_us=now_us;return BILI_LIVE_ANCHOR;
  }
  if(period_us&&now_us/period_us==p->last_present_us/period_us)return BILI_LIVE_SKIP_SLOT;
  p->last_pts=pts;p->last_present_us=now_us;return BILI_LIVE_PRESENT;
}
